package com.servicerca.controller;import com.servicerca.dto.rating.*;import com.servicerca.security.SecurityUser;import com.servicerca.service.RatingService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/v1/requests/{requestId}/ratings")public class RatingController{private final RatingService service;public RatingController(RatingService s){service=s;}@PostMapping public ResponseEntity<RatingResponse>create(@AuthenticationPrincipal SecurityUser u,@PathVariable UUID requestId,@Valid@RequestBody CreateRatingRequest r){return ResponseEntity.status(201).body(service.create(u.user(),requestId,r));}}
